// App.js
import React, { useState } from 'react';
import { Grommet, Box, Meter, Button } from 'grommet';

export default function App() {
  const [value, setValue] = useState(25);

  return (
    <Grommet>
      <Box align="center" pad="large">
        {/* circle Meter with default transition on its <path> */}
        <Meter
          type="circle"
          size="medium"
          thickness="medium"
          values={[{ value, color: 'status-critical' }]} 
        />
        {/* button to change the value and trigger the transition */}
        <Button
          label="Random %"
          margin={{ top: 'medium' }}
          onClick={() => setValue(Math.floor(Math.random() * 100) + 1)}
        />
      </Box>
    </Grommet>
  );
}

// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import App from './App';

ReactDOM.render(<App />, document.getElementById('root'));

